add(s,'c1','higher digit, For example, 0.756 = 0.76 and 0.677 = 0.68.','اعلیٰ ہندسے تک بڑھا دیا جاتا ہے، مثال کے طور پر 0.756 = 0.76 اور 0.677 = 0.68۔','لوړې رقم ته پورته کېږي، د مثال په توګه 0.756 = 0.76 او 0.677 = 0.68.',sourceGap=dict(note='The first words of this sentence are carried over from the previous page ("…raised to the next").'))
head(s,'riii','Rule-iii','قاعدہ-iii','قاعده-iii')
add(s,'triii','If the last digit ends in 5 and the digit preceding the 5 is an even number, then 5 is dropped, For example, 0.725 = 0.72 and 0.665 = 0.66','اگر آخری ہندسہ 5 پر ختم ہو اور 5 سے پہلے والا ہندسہ جفت عدد ہو تو 5 کو چھوڑ دیا جاتا ہے، مثال کے طور پر 0.725 = 0.72 اور 0.665 = 0.66','که وروستی رقم په 5 پای ته ورسېږي او د 5 مخکینۍ رقم جفت عدد وي نو 5 لرې کېږي، د مثال په توګه 0.725 = 0.72 او 0.665 = 0.66')
